166	class FeatureCardCanvasRuntime {
167	  private _instances: FeatureCardCanvasInstance[] = [];
168	  private _rafId: number | null = null;
169	  private _resizeListener: (() => void) | null = null;
170	
171	  init(root?: ParentNode | null): void {
172	    this.dispose();
173	    const scope = root ?? document;
174	    const cardList = scope.querySelector<HTMLElement>(
175	      FEATURE_CARD_CANVAS.listSelector,
176	    );
177	    if (!cardList) return;
178	    const canvasElements = Array.from(
179	      cardList.querySelectorAll<HTMLCanvasElement>(
180	        FEATURE_CARD_CANVAS.canvasSelector,
181	      ),
182	    );
183	    if (canvasElements.length === 0) return;
184	
185	    this._instances = canvasElements.flatMap((canvas, index) => {
186	      const context = canvas.getContext("2d");
187	      if (!context) return [];
188	      return [
189	        {
190	          canvas,
191	          context,
192	          size: { width: 0, height: 0, dpr: 1 },
193	          rotation: index * 0.45,
194	          tilt: 0.6 + index * 0.18,
195	          speed:
196	            FEATURE_CARD_CANVAS.rotationSpeedBase +
197	            index * FEATURE_CARD_CANVAS.rotationSpeedStep,
198	          particles: this._createParticles(index),
199	        },
200	      ];
201	    });
202	
203	    if (this._instances.length === 0) return;
204	
205	    this._resizeListener = () => this._resize();
206	    window.addEventListener("resize", this._resizeListener);
207	    this._resize();
208	    this._startLoop();
209	  }
210	
211	  dispose(): void {
212	    if (this._rafId !== null) {
213	      FrameScheduler.cancel(this._rafId);
214	      this._rafId = null;
215	    }
216	    if (this._resizeListener) {
217	      window.removeEventListener("resize", this._resizeListener);
218	      this._resizeListener = null;
219	    }
220	    this._instances = [];
221	  }
222	
223	  private _startLoop(): void {
224	    const render = (): void => {
225	      this._render();
226	      this._rafId = FrameScheduler.request(render);
227	    };
228	    render();
229	  }
230	
231	  private _resize(): void {
232	    const dpr = Math.min(
233	      ResponsiveRuntime.getDefault().getSnapshot().render.clampedPixelRatio,
234	      FEATURE_CARD_CANVAS.pixelRatioMax,
235	    );
236	    this._instances.forEach((instance) => {
237	      const bounds = instance.canvas.getBoundingClientRect();
238	      const width = Math.max(1, Math.round(bounds.width));
239	      const height = Math.max(1, Math.round(bounds.height));
240	      instance.size = { width, height, dpr };
241	      instance.canvas.width = Math.round(width * dpr);
242	      instance.canvas.height = Math.round(height * dpr);
243	      instance.context.setTransform(dpr, 0, 0, dpr, 0, 0);
244	    });
245	  }
246	
247	  private _render(): void {
248	    this._instances.forEach((instance) => {
249	      const { context, size } = instance;
250	      if (size.width <= 0 || size.height <= 0) return;
251	
252	      instance.rotation += instance.speed;
253	      context.clearRect(0, 0, size.width, size.height);
254	      context.fillStyle = FEATURE_CARD_CANVAS.clearColor;
255	      context.fillRect(0, 0, size.width, size.height);
256	
257	      this._drawParticles(instance);
258	      this._drawCube(instance);
259	    });
260	  }
261	
262	  private _drawParticles(instance: FeatureCardCanvasInstance): void {
263	    const { context, size, rotation, particles } = instance;
264	    const halfWidth = size.width * 0.5;
265	    const halfHeight = size.height * 0.5;
266	    const scale =
267	      Math.min(size.width, size.height) * FEATURE_CARD_CANVAS.cubeScale;
268	
269	    context.fillStyle = FEATURE_CARD_CANVAS.particleColor;
270	    particles.forEach((particle) => {
271	      const spin = rotation * (0.6 + particle.drift * 0.4);
272	      const cos = Math.cos(spin);
273	      const sin = Math.sin(spin);
274	      const rotatedX = particle.x * cos - particle.z * sin;
275	      const rotatedZ = particle.x * sin + particle.z * cos;
276	      const depth = rotatedZ + 3.6;
277	      const perspective = 1 / depth;
278	      const drawX = halfWidth + rotatedX * scale * perspective;
279	      const drawY =
280	        halfHeight +
281	        (particle.y + Math.sin(rotation + particle.drift) * 0.14) *
282	          scale *
283	          perspective;
284	      const drawSize = particle.size * perspective * 4.5;
285	      context.fillRect(drawX, drawY, drawSize, drawSize);
286	    });
287	  }
288	
289	  private _drawCube(instance: FeatureCardCanvasInstance): void {
290	    const { context, size, rotation, tilt } = instance;
291	    const halfWidth = size.width * 0.5;
292	    const halfHeight = size.height * 0.5;
293	    const scale =
294	      Math.min(size.width, size.height) * FEATURE_CARD_CANVAS.cubeScale;
295	    const projected = FEATURE_CARD_CUBE_VERTICES.map(([x, y, z]) => {
296	      const rotatedY = this._rotateY(x, z, rotation);
297	      const rotatedX = this._rotateX(y, rotatedY.z, tilt);
298	      const depth = rotatedX.z + 4.2;
299	      const perspective = 1 / depth;
300	      return {
301	        x: halfWidth + rotatedY.x * scale * perspective,
302	        y: halfHeight + rotatedX.y * scale * perspective,
303	      };
304	    });
305	
306	    context.fillStyle = FEATURE_CARD_CANVAS.fillStyle;
307	    context.beginPath();
308	    context.moveTo(projected[4].x, projected[4].y);
309	    context.lineTo(projected[5].x, projected[5].y);
310	    context.lineTo(projected[6].x, projected[6].y);
311	    context.lineTo(projected[7].x, projected[7].y);
312	    context.closePath();
313	    context.fill();
314	
315	    context.strokeStyle = FEATURE_CARD_CANVAS.strokeStyle;
316	    context.lineWidth = 1.2;
317	    FEATURE_CARD_CUBE_EDGES.forEach(([startIndex, endIndex]) => {
318	      const start = projected[startIndex];
319	      const end = projected[endIndex];
320	      context.beginPath();
321	      context.moveTo(start.x, start.y);
322	      context.lineTo(end.x, end.y);
323	      context.stroke();
324	    });
325	  }
326	
327	  private _createParticles(index: number): FeatureCardCanvasParticle[] {
328	    return Array.from(
329	      { length: FEATURE_CARD_CANVAS.particleCount },
330	      (_, particleIndex) => {
331	        const seed = (index + 1) * (particleIndex + 3);
332	        const angle = seed * 0.73;
333	        const radius = 1.2 + (particleIndex % 5) * 0.18;
334	        return {
335	          x: Math.cos(angle) * radius,
336	          y: (((particleIndex % 7) - 3) / 3) * 1.35,
337	          z: Math.sin(angle) * radius,
338	          size:
339	            FEATURE_CARD_CANVAS.particleSizeMin +
340	            (particleIndex % 4) *
341	              ((FEATURE_CARD_CANVAS.particleSizeMax -
342	                FEATURE_CARD_CANVAS.particleSizeMin) /
343	                3),
344	          drift: 0.8 + (particleIndex % 6) * 0.12,
345	        };
346	      },
347	    );
348	  }
349	
350	  private _rotateY(
351	    x: number,
352	    z: number,
353	    angle: number,
354	  ): { x: number; z: number } {
355	    const cos = Math.cos(angle);
356	    const sin = Math.sin(angle);
357	    return {
358	      x: x * cos - z * sin,
359	      z: x * sin + z * cos,
360	    };
361	  }
362	
363	  private _rotateX(
364	    y: number,
365	    z: number,
366	    angle: number,
367	  ): { y: number; z: number } {
368	    const cos = Math.cos(angle);
369	    const sin = Math.sin(angle);
370	    return {
371	      y: y * cos - z * sin,
372	      z: y * sin + z * cos,
373	    };
374	  }
375	}
